    try (ZkStateReader zkStateReader = ClusterStateMockUtil.buildClusterState("csr*sr2", "baseUrl1:8983_")) {
        CloudReplicaSource cloudReplicaSource = new CloudReplicaSource.Builder().collection("collection1").onlyNrt(false).zkStateReader(zkStateReader).replicaListTransformer(replicaListTransformer).allowListUrlChecker(checker).params(params).build();
        assertEquals(2, cloudReplicaSource.getSliceCount());
        assertEquals(2, cloudReplicaSource.getSliceNames().size());
