        assertEquals(0, cloudReplicaSource.getReplicasBySlice(1).size());
    }
}

@Test
public void testShardsParam_DownReplica() {
    ReplicaListTransformer replicaListTransformer = Mockito.mock(ReplicaListTransformer.class);
